function operating(base: ModelInputs, capacity: number, unit: ReturnType<typeof L>, setup: BudgetRow[], fixed: BudgetRow[], workingCapital: BudgetRow[], ramp: number[], conservative: ModelInputs, optimistic: ModelInputs): ModelConfig {
  const inputs = { ...base, setup: total(setup), fixed: total(fixed), workingCapital: total(workingCapital) };
  return { kind: 'operating', base: inputs, unit, capacity, setup, fixed, workingCapital, ramp, conservative: { ...inputs, ...conservative }, optimistic: { ...inputs, ...optimistic } };
}

