export function getPortfolioFeasibility(slug: string): PortfolioFeasibilityStudy {
  const study = PORTFOLIO_FEASIBILITY.find(item => item.slug === slug);
  if (!study) throw new Error(`Unknown feasibility study: ${slug}`);
  return study;
}
